result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/observation_validator.py", "content": """"Educational FHIR-style Observation resource validator.

Stdlib only (json / re). No external validation libraries.

Returns structured results:
    {
        "valid": bool,
        "errors": [{"path": "/valueQuantity/value", "message": "..."}],
        "interpretation": "L" | "N" | "H"   # only when computable
    }

Error paths are JSON-pointer style (RFC 6901), rooted at the resource.
"""

import re

ALLOWED_STATUS = {"registered", "preliminary", "final", "amended"}
UCUM_SYSTEM = "http://unitsofmeasure.example"
PATIENT_REF_RE = re.compile(r"^Patient/[A-Za-z0-9\-._]{1,64}$")


def _error(path, message):
    return {"path": path, "message": message}


def _validate_value_quantity(res):
    """Validate valueQuantity; return list of errors."""
    errors = []
    vq = res.get("valueQuantity")

    if vq is None:
        return errors

    if not isinstance(vq, dict):
        return [_error("/valueQuantity", "valueQuantity must be an object")]

    if "value" not in vq:
        errors.append(_error("/valueQuantity/value", "value is required"))
    elif isinstance(vq["value"], bool) or not isinstance(vq["value"], (int, float)):
        errors.append(_error("/valueQuantity/value", "value must be a number"))

    if "unit" not in vq:
        errors.append(_error("/valueQuantity/unit", "unit is required"))
    elif not isinstance(vq["unit"], str) or not vq["unit"]:
        errors.append(_error("/valueQuantity/unit", "unit must be a non-empty string"))

    if "system" not in vq:
        errors.append(_error("/valueQuantity/system", "system is required"))
    elif vq["system"] != UCUM_SYSTEM:
        errors.append(
            _error(
                "/valueQuantity/system",
                f'system must be fixed to "{UCUM_SYSTEM}"',
            )
        )

    return errors


def _validate_reference_range(res):
    """Validate referenceRange; return list of errors.

    Assumes valueQuantity (if present) has already been checked.
    """
    errors = []
    rr = res.get("referenceRange")
    if rr is None:
        return errors

    if not isinstance(rr, dict):
        return [_error("/referenceRange", "referenceRange must be an object")]

    low = rr.get("low")
    high = rr.get("high")

    for name in ("low", "high"):
        bound = rr.get(name)
        if bound is None:
            errors.append(_error(f"/referenceRange/{name}", f"{name} is required"))
            continue
        if not isinstance(bound, dict):
            errors.append(_error(f"/referenceRange/{name}", f"{name} must be an object"))
            continue
        val = bound.get("value")
        if val is None:
            errors.append(_error(f"/referenceRange/{name}/value", f"{name}.value is required"))
        elif isinstance(val, bool) or not isinstance(val, (int, float)):
            errors.append(_error(f"/referenceRange/{name}/value", f"{name}.value must be a number"))
        unit = bound.get("unit")
        if unit is None:
            errors.append(_error(f"/referenceRange/{name}/unit", f"{name}.unit is required"))
        elif not isinstance(unit, str) or not unit:
            errors.append(_error(f"/referenceRange/{name}/unit", f"{name}.unit must be a non-empty string"))

    # Cross-checks need well-formed bounds.
    low_v = low.get("value") if isinstance(low, dict) else None
    high_v = high.get("value") if isinstance(high, dict) else None
    low_u = low.get("unit") if isinstance(low, dict) else None
    high_u = high.get("unit") if isinstance(high, dict) else None

    nums = lambda v: isinstance(v, (int, float)) and not isinstance(v, bool)
    if nums(low_v) and nums(high_v) and not (low_v < high_v):
        errors.append(
            _error(
                "/referenceRange",
                f"low.value ({low_v}) must be strictly less than high.value ({high_v})",
            )
        )
    vq_unit = res.get("valueQuantity", {}).get("unit") if isinstance(res.get("valueQuantity"), dict) else None
    if vq_unit is not None:
        if low_u is not None and low_u != vq_unit:
            errors.append(
                _error(
                    "/referenceRange/low/unit",
                    f'low.unit "{low_u}" does not match valueQuantity.unit "{vq_unit}"',
                )
            )
        if high_u is not None and high_u != vq_unit:
            errors.append(
                _error(
                    "/referenceRange/high/unit",
                    f'high.unit "{high_u}" does not match valueQuantity.unit "{vq_unit}"',
                )
            )

    return errors


def interpret(value, low, high):
    """Return "L", "N", or "H". Boundary equality counts as "N".

    Caller guarantees all three are numbers and low < high.
    """
    if value < low:
        return "L"
    if value > high:
        return "H"
    return "N"


def validate(res):
    """Validate an Observation resource. Returns a result dict (never raises)."""
    errors = []
    interpretation = None

    if not isinstance(res, dict):
        return {
            "valid": False,
            "errors": [_error("", "resource must be a JSON object")],
            "interpretation": None,
        }

    # --- resourceType ---
    if res.get("resourceType") != "Observation":
        errors.append(
            _error("/resourceType", 'resourceType must be "Observation"')
        )

    # --- status ---
    status = res.get("status")
    if status not in ALLOWED_STATUS:
        errors.append(
            _error(
                "/status",
                f'status must be one of {sorted(ALLOWED_STATUS)}',
            )
        )

    # --- code.text ---
    code = res.get("code")
    if not isinstance(code, dict):
        errors.append(_error("/code", "code must be an object"))
    else:
        text = code.get("text")
        if not isinstance(text, str) or not text.strip():
            errors.append(_error("/code/text", "code.text must be a non-empty string"))

    # --- subject.reference ---
    subject = res.get("subject")
    ref_ok = False
    if not isinstance(subject, dict):
        errors.append(_error("/subject", "subject must be an object"))
    else:
        ref = subject.get("reference")
        if not isinstance(ref, str) or not PATIENT_REF_RE.match(ref):
            errors.append(
                _error(
                    "/subject/reference",
                    'subject.reference must match "Patient/<id>"',
                )
            )
        else:
            ref_ok = True

    # --- valueQuantity ---
    vq_errors = _validate_value_quantity(res)
    errors.extend(vq_errors)
    has_vq = isinstance(res.get("valueQuantity"), dict) and not any(
        e["path"].startswith("/valueQuantity") for e in vq_errors
    )

    # --- cross-field rule: status "final" requires valueQuantity ---
    if status == "final" and res.get("valueQuantity") is None:
        errors.append(
            _error(
                "/valueQuantity",
                'valueQuantity is required when status is "final"',
            )
        )

    # --- referenceRange ---
    rr_errors = _validate_reference_range(res)
    errors.extend(rr_errors)

    # --- interpretation ---
    rr = res.get("referenceRange") if isinstance(res.get("referenceRange"), dict) else None
    if has_vq and rr is not None and not rr_errors:
        value = res["valueQuantity"]["value"]
        low = rr["low"]["value"]
        high = rr["high"]["value"]
        interpretation = interpret(value, low, high)

    return {
        "valid": not errors,
        "errors": errors,
        "interpretation": interpretation,
    }


def validate_json(text):
    """Convenience wrapper: parse JSON text and validate."""
    try:
        res = json.loads(text)
    except ValueError as exc:
        return {
            "valid": False,
            "errors": [_error("", f"invalid JSON: {exc}")],
            "interpretation": None,
        }
    return validate(res)


import json  # noqa: E402  (kept at bottom so validate() stays import-clean above)


__all__ = ["validate", "validate_json", "interpret"]
"})
