result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test_observation_validator.py", "content": "import copy

import pytest

from observation_validator import UCUM_SYSTEM, validate


def make_resource(**overrides):
    base = {
        "resourceType": "Observation",
        "status": "preliminary",
        "code": {"text": "Hemoglobin"},
        "subject": {"reference": "Patient/123"},
        "valueQuantity": {
            "value": 13.5,
            "unit": "g/dL",
            "system": UCUM_SYSTEM,
        },
    }
    base.update(overrides)
    return base


def deep_merge(base, extra):
    out = copy.deepcopy(base)
    for k, v in extra.items():
        if isinstance(v, dict) and isinstance(out.get(k), dict):
            out[k] = deep_merge(out[k], v)
        else:
            out[k] = v
    return out


def paths(result):
    return [e["path"] for e in result["errors"]]


# ---------------------------------------------------------------------------
# Matrix: 4 statuses x value present/absent
# ---------------------------------------------------------------------------

STATUSES = ["registered", "preliminary", "final", "amended"]


@pytest.mark.parametrize("status", STATUSES)
def test_matrix_value_present_valid(status):
    result = validate(make_resource(status=status))
    assert result["valid"], result["errors"]


@pytest.mark.parametrize("status", STATUSES)
def test_matrix_value_absent(status):
    res = make_resource(status=status)
    del res["valueQuantity"]
    result = validate(res)

    if status == "final":
        assert not result["valid"]
        assert "/valueQuantity" in paths(result)
        assert any("required" in e["message"] for e in result["errors"])
    else:
        assert result["valid"], result["errors"]


def test_matrix_null_value_counts_as_absent():
    res = make_resource(status="final", valueQuantity=None)
    result = validate(res)
    assert not result["valid"]
    assert "/valueQuantity" in paths(result)


# ---------------------------------------------------------------------------
# Field-level schema violations
# ---------------------------------------------------------------------------


def test_wrong_resource_type():
    result = validate(make_resource(resourceType="Procedure"))
    assert "/resourceType" in paths(result)


@pytest.mark.parametrize("status", ["draft", "", None, "FINAL"])
def test_bad_status(status):
    result = validate(make_resource(status=status))
    assert "/status" in paths(result)


def test_empty_code_text():
    result = validate(make_resource(code={"text": ""}))
    assert "/code/text" in paths(result)


def test_whitespace_only_code_text():
    result = validate(make_resource(code={"text": "   "}))
    assert "/code/text" in paths(result)


@pytest.mark.parametrize("ref", ["Observation/1", "patient/9", "Patient/", "Patient/ab cd", "Patient"])
def test_bad_subject_reference(ref):
    result = validate(make_resource(subject={"reference": ref}))
    assert "/subject/reference" in paths(result)


def test_bad_system():
    res = make_resource()
    res["valueQuantity"]["system"] = "http://loinc.org"
    result = validate(res)
    assert "/valueQuantity/system" in paths(result)


def test_non_numeric_value():
    res = make_resource()
    res["valueQuantity"]["value"] = "13.5"
    result = validate(res)
    assert "/valueQuantity/value" in paths(result)
    assert not result["valid"]


def test_missing_unit_and_numeric_string_value():
    res = make_resource()
    del res["valueQuantity"]["unit"]
    result = validate(res)
    assert "/valueQuantity/unit" in paths(result)


# ---------------------------------------------------------------------------
# referenceRange violations
# ---------------------------------------------------------------------------


def add_range(res, low=12.0, high=16.0, unit="g/dL"):
    return deep_merge(
        res,
        {
            "referenceRange": {
                "low": {"value": low, "unit": unit},
                "high": {"value": high, "unit": unit},
            }
        },
    )


def test_low_greater_than_high():
    result = validate(add_range(make_resource(), low=17.0, high=16.0))
    assert not result["valid"]
    assert "/referenceRange" in paths(result)


def test_low_equal_to_high():
    result = validate(add_range(make_resource(), low=16.0, high=16.0))
    assert not result["valid"]
    assert "/referenceRange" in paths(result)
    assert any("strictly less" in e["message"] for e in result["errors"])


def test_low_unit_mismatch():
    result = validate(add_range(make_resource(), low=12.0, high=16.0, unit="mg/L"))
    assert not result["valid"]
    assert "/referenceRange/low/unit" in paths(result)


def test_high_unit_mismatch():
    result = validate(add_range(make_resource(), low=12.0, high=16.0, unit="mmol/L"))
    # both bounds share the wrong unit -> two mismatch errors
    assert "/referenceRange/high/unit" in paths(result)
    assert "/referenceRange/low/unit" in paths(result)


def test_range_bound_pointing_at_correct_pointer():
    result = validate(add_range(make_resource(), low=17.0, high=16.0))
    assert "/referenceRange" in paths(result)  # cross-field pointer, not nested


# ---------------------------------------------------------------------------
# Interpretation: L / N / H, boundaries count as N
# ---------------------------------------------------------------------------

RANGE = {"low": {"value": 4.0, "unit": "mmol/L"}, "high": {"value": 8.0, "unit": "mmol/L"}}


def interp_case(value, status="preliminary"):
    res = deep_merge(
        make_resource(),
        {
            "status": status,
            "valueQuantity": {"value": value, "unit": "mmol/L", "system": UCUM_SYSTEM},
            "referenceRange": RANGE,
        },
    )
    return validate(res)


@pytest.mark.parametrize("value,expected", [(3.99, "L"), (4.0, "N"), (6.0, "N"), (8.0, "N"), (8.01, "H")])
def test_interpretation_sides_and_boundaries(value, expected):
    result = interp_case(value)
    assert result["valid"], result["errors"]
    assert result["interpretation"] == expected


def test_interpretation_none_without_reference_range():
    result = validate(make_resource())
    assert result["valid"]
    assert result["interpretation"] is None


def test_no_interpretation_when_range_invalid():
    result = validate(add_range(make_resource(), low=20.0, high=10.0))
    assert not result["valid"]
    assert result["interpretation"] is None


def test_no_interpretation_when_value_absent():
    res = add_range(make_resource())
    del res["valueQuantity"]
    result = validate(res)
    assert result["valid"]  # preliminary without value is fine
    assert result["interpretation"] is None


# ---------------------------------------------------------------------------
# Fully valid fixtures
# ---------------------------------------------------------------------------

FIXTURE_1 = {
    "resourceType": "Observation",
    "status": "final",
    "code": {"text": "Serum Glucose"},
    "subject": {"reference": "Patient/p-0001"},
    "valueQuantity": {"value": 5.4, "unit": "mmol/L", "system": "http://unitsofmeasure.example"},
}

FIXTURE_2 = {
    "resourceType": "Observation",
    "status": "amended",
    "code": {"text": "Blood Pressure, systolic"},
    "subject": {"reference": "Patient/x9.y-z_8"},
    "valueQuantity": {"value": 118, "unit": "mmHg", "system": "http://unitsofmeasure.example"},
    "referenceRange": {
        "low": {"value": 90, "unit": "mmHg"},
        "high": {"value": 120, "unit": "mmHg"},
    },
}


def test_fixture_1_final_with_value_is_valid():
    result = validate(FIXTURE_1)
    assert result["valid"], result["errors"]
    assert result["interpretation"] is None  # no referenceRange


def test_fixture_2_full_resource_is_valid():
    result = validate(FIXTURE_2)
    assert result["valid"], result["errors"]
    assert result["interpretation"] == "N"  # 118 within [90, 120]


def test_fixture_boundary_low_counts_normal():
    res = copy.deepcopy(FIXTURE_2)
    res["valueQuantity"]["value"] = 90
    assert validate(res)["interpretation"] == "N"


def test_fixture_boundary_high_counts_normal():
    res = copy.deepcopy(FIXTURE_2)
    res["valueQuantity"]["value"] = 120
    assert validate(res)["interpretation"] == "N"
